import sqlite3

def browse_invoices(db_path, order_column, page_size):
    connection = sqlite3.connect(db_path)
    try:
        cursor = connection.cursor()
        query = f"SELECT * FROM invoices ORDER BY {order_column} DESC LIMIT {page_size}"
        cursor.execute(query)
        return cursor.fetchall()
    finally:
        connection.close()

